function model(p) {
  // How a lesson made in the lab reaches people: everyone starts the same way (describe, spec, generate, export), then
  // the exported file either goes into one browser (Import lesson: instant, temporary, that browser only) or into the
  // repository's gallery (add-lesson, push, CI, Pages: slower, permanent, everyone). Minutes are illustrative.
  const route = Math.round(p.route) === 1 ? 'publish' : 'import';
  const ciPass = Math.round(p.ci) === 0;
  const viewer = Math.max(0, Math.min(2, Math.round(p.viewer)));
  const viewers = [
    { id: 'same', label: 'You, same browser', saw: 'you see it', missed: 'you do not see it' },
    { id: 'cleared', label: 'You, after clearing the browser', saw: 'it is still there after clearing', missed: 'clearing the browser erased it' },
    { id: 'colleague', label: 'A colleague, on their computer', saw: 'a colleague sees it', missed: 'a colleague does not see it' }
  ];
  const lanes = [
    { id: 'claude', label: 'Lab on claude.ai' },
    { id: 'computer', label: 'Your computer' },
    { id: 'browser', label: 'One browser' },
    { id: 'repo', label: 'Repository' },
    { id: 'ci', label: 'GitHub Actions' },
    { id: 'site', label: 'Published site' }
  ];
  const common = [
    { id: 'describe', lane: 'claude', title: 'Describe the goal', min: 2, note: 'You describe the concept in plain words in the lab, opened on claude.ai, where Claude is available.' },
    { id: 'spec', lane: 'claude', title: 'Draft the spec', min: 1, note: 'Claude writes the objective, the model, the controls and the check. You read it before anything is drawn.' },
    { id: 'generate', lane: 'claude', title: 'Generate versions', min: 4, note: 'Each library draws the same model; every version must pass the same check.' },
    { id: 'export', lane: 'computer', title: 'Export lesson', min: 0.2, note: 'Export lesson saves the whole lesson (spec, versions and notes) as one .lesson.json file on your computer.' }
  ];
  const importSteps = [
    { id: 'import', lane: 'browser', title: 'Import lesson', min: 0.2, note: 'Import lesson reads the file into this browser\'s own storage. It shows at once, but only here: nothing is uploaded.' }
  ];
  const deploy = { id: 'deploy', lane: 'site', title: 'Deploy to Pages', min: 2, note: 'The tests are green, so the pages workflow publishes the new build.' };
  const publishSteps = [
    { id: 'add', lane: 'computer', title: 'npm run add-lesson', min: 2, note: 'The script checks the spec, the libraries and the chart forms, verifies every version in Chromium and writes it into gallery/items/.' },
    { id: 'push', lane: 'repo', title: 'Commit and push', min: 1, note: 'git push sends the new gallery lesson to the repository on GitHub.' },
    { id: 'ci', lane: 'ci', title: 'Tests and gallery build', min: 40, note: 'GitHub Actions runs the tests and rebuilds and verifies the whole gallery, because a lesson changed.' },
    ciPass
      ? deploy
      : { id: 'fail', lane: 'ci', title: 'Run fails: nothing deploys', min: 0, bad: true, note: 'A test fails, so nothing is published; the site keeps its last good version until a fix is pushed.' }
  ];
  const visible = route === 'publish' ? ciPass : viewer === 0;
  const persistent = route === 'publish' && ciPass;
  const audience = route === 'publish' ? (ciPass ? 'everyone who opens the site' : 'nobody new yet') : 'whoever uses that one browser';
  const outcome = route === 'import'
    ? { id: 'outcome', lane: 'browser', title: visible ? 'Visible here only' : 'Not visible', min: 0, bad: !visible,
        note: viewer === 0 ? 'You see it in this browser. It is gone if the browser\'s site data is cleared, and nobody else has it.' : viewer === 1 ? 'Clearing the browser\'s site data erased it: an import lives only in that browser\'s storage.' : 'Your colleague does not see it. They would need the file and their own Import, and it would still live only in their browser.' }
    : { id: 'outcome', lane: 'site', title: visible ? 'In the gallery for everyone' : 'Not published', min: 0, bad: !visible,
        note: visible ? viewers[viewer].label + ' sees it under Get inspired, and so does anyone else, until it is removed from the repository.' : 'Nobody sees the new lesson on the site yet. Fix the failing test, push again, and the next green run publishes it.' };
  const path = common.concat(route === 'import' ? importSteps : publishSteps, [outcome]);
  const other = route === 'import' ? publishSteps.slice(0, 3).concat([deploy]) : importSteps;   // the other way, drawn faintly for comparison (a green publish)
  // Real minutes run back to back; playback gives every step the same time so short steps can be read
  let m0 = 0;
  const per = 1.7;
  const steps = path.map((s, i) => { const st = Object.assign({}, s, { t: +(i * per).toFixed(2), startMin: +m0.toFixed(1), endMin: +(m0 + s.min).toFixed(1) }); m0 += s.min; return st; });
  const totalMin = +m0.toFixed(1);
  // minutes until the lesson shows anywhere: in the importing browser, or on the site after a green run
  const shownAtMin = route === 'import' ? steps.find(s => s.id === 'import').endMin : ciPass ? steps.find(s => s.id === 'deploy').endMin : null;
  let o0 = steps[3].endMin;
  const otherSteps = other.map(s => { const st = Object.assign({}, s, { startMin: +o0.toFixed(1), endMin: +(o0 + s.min).toFixed(1) }); o0 += s.min; return st; });
  const sum = list => +list.reduce((a, s) => a + s.min, 0).toFixed(1);
  const importMinutes = sum(common.concat(importSteps)), publishMinutes = sum(common.concat(publishSteps.slice(0, 3), [deploy]));
  const lanesUsed = lanes.map(l => l.id).filter(id => steps.some(s => s.lane === id));
  const duration = +(steps.length * per + 0.6).toFixed(2);
  const markers = steps.map(s => s.t);
  const summary = route === 'import'
    ? ['Imported: on screen after ' + shownAtMin.toFixed(1) + ' min in this browser; nobody else sees it, and clearing the browser erases it.',
       'Imported: it showed after ' + shownAtMin.toFixed(1) + ' min in one browser, and clearing that browser erased it.',
       'Imported: it shows after ' + shownAtMin.toFixed(1) + ' min in your browser only; a colleague does not see it.'][viewer]
    : ciPass ? 'Published: in the gallery for everyone after ' + shownAtMin.toFixed(0) + ' min (add-lesson, push, tests, deploy), and it stays.'
      : 'Push made, but a test failed: nothing is published and the site keeps its last good version.';
  return { route, ciPass, viewer, viewerLabel: viewers[viewer].label, viewerSees: viewers[viewer].saw, viewerMisses: viewers[viewer].missed, viewers, lanes, lanesUsed, steps, other: { route: route === 'import' ? 'publish' : 'import', steps: otherSteps }, visible, persistent, audience,
    shownAtMin, importMinutes, publishMinutes, totalMinutes: totalMin, duration, markers, summary,
    viewerResults: viewers.map((v, i) => ({ id: v.id, label: v.label, sees: route === 'publish' ? ciPass : i === 0 })) };
}

checkCode:
function check(p) {
  const m = model(p), lanes = new Set(m.steps.map(s => s.lane));
  // Who sees the lesson follows from the route alone: an import lives in one browser, a green publish reaches everyone
  const visibleOk = m.visible === (m.route === 'publish' ? m.ciPass : m.viewer === 0)
    && m.viewerResults.every((v, i) => v.sees === (m.route === 'publish' ? m.ciPass : i === 0));
  const persistentOk = m.persistent === (m.route === 'publish' && m.ciPass);
  // A temporary import never leaves the browser; only the publish route touches the repository, CI and the site
  const lanesOk = m.route === 'import' ? !lanes.has('repo') && !lanes.has('ci') && !lanes.has('site') : lanes.has('repo') && lanes.has('ci');
  const deployOk = m.route === 'publish' ? m.steps.some(s => s.id === 'deploy') === m.ciPass : true;
  // Minutes run back to back and add up; playback markers are ordered
  const r = v => Math.round(v * 10) / 10;
  const seqOk = m.steps.every((s, i) => i === 0 || r(s.startMin) === r(m.steps[i - 1].endMin)) && r(m.steps[m.steps.length - 1].endMin) === r(m.totalMinutes);
  const markersOk = m.markers.every((t, i) => i === 0 || t > m.markers[i - 1]) && m.markers[m.markers.length - 1] < m.duration;
  // The trade the lesson teaches: an import is quicker than a green publish, and only the publish lasts and reaches everyone
  const tradeOk = m.importMinutes < m.publishMinutes && (m.shownAtMin == null ? m.route === 'publish' && !m.ciPass : m.shownAtMin === (m.route === 'import' ? m.importMinutes : m.publishMinutes));
  const pass = visibleOk && persistentOk && lanesOk && deployOk && seqOk && markersOk && tradeOk;
  return { pass,
    detail: (m.route === 'import' ? 'Import: ' + (m.visible ? m.viewerSees : m.viewerMisses) + '; it lives in one browser only, never in the repository or on the site'
      : m.ciPass ? 'Publish: everyone sees it on the site, permanently' : 'Publish with a failing test: nothing deploys, nobody sees it')
      + (visibleOk && persistentOk && lanesOk && deployOk ? '' : ' (route rules broken)')
      + '; an import shows after ' + m.importMinutes.toFixed(1) + ' min, a green publish after ' + m.publishMinutes.toFixed(0) + ' min' + (seqOk && tradeOk ? '' : ' (minutes do not add up)') + '.' };
}
